    size_t i;
    if (kz_live_tasks() >= kz_task_ceiling())
        kz_conc_fail("E_KAZE_TASK_BOUND", "the task ceiling is reached; raise KAZE_MAX_TASKS or spawn fewer tasks");
    f = (kz_fiber*)kz_alloc(sizeof(kz_fiber));
    f->parent = kz_current;
    f->next = NULL;
    f->step = step;
    f->slot_count = slot_count;
