    h = kz_add_own(h, kz_str("    return kz_alloc_raw(n);\n"));
    h = kz_add_own(h, kz_str("}\n"));
    h = kz_add_own(h, kz_str("static void kz_print_alloc_sites(void) {\n"));
    h = kz_add_own(h, kz_str("    const char* env = getenv(\"KAZE_ARENA_STATS\");\n"));
