    h = kz_add_own(h, kz_str("    }\n"));
    h = kz_add_own(h, kz_str("}\n\n"));
    h = kz_add_own(h, kz_str("KZ_MAYBE_UNUSED static inline const char* kz_to_string(KzValue v) {\n"));
